            "bz_use_review": "Ưu tiên kiểm tra môi trường",
            "bz_action_activity": "Dọn thoáng lối đi, cửa và cải thiện ánh sáng, thông gió. Nếu phù hợp làm việc hoặc sinh hoạt, bố trí bàn ghế và lối di chuyển.",
            "bz_action_rest": "Kiểm tra ghế nghỉ, chỗ tựa giường, tiếng ồn và chói sáng ban đêm. Nếu là phòng khách, sắp chỗ ngồi thoải mái và khu trò chuyện ít bị quấy rầy.",
            "bz_action_study": "Giữ bàn gọn, ghế chắc và ánh sáng dễ chịu; tránh nguồn ồn liên tục rồi điều chỉnh theo thói quen học hay làm việc.",
            "bz_action_review": "Kiểm tra việc nằm ngủ hay ngồi lâu cùng thông gió, ánh sáng, tiếng ồn và đồ bừa bộn. Giải quyết bất tiện thực tế trước rồi chỉnh nhỏ.",
            "bz_avoid_activity": "Không cần đổi cửa, mua bể cá hay chuyển đồ lớn chỉ vì nhãn cát; đừng để vật trang trí chắn lối.",
            "bz_avoid_rest": "Tên sao không đánh giá giấc ngủ hay sức khỏe; không cần chuyển giường chỉ theo phương vị. Ưu tiên sự thoải mái thực tế.",
            "bz_avoid_study": "Tránh ngược sáng, chói màn hình và lối đi xuyên chỗ ngồi; không cần mua vật phẩm học hành đặc biệt.",
            "bz_avoid_review": "Tên hung tinh truyền thống không kết luận tai nạn thực tế. Không cần ngừng dùng phòng, đổi thành nhà vệ sinh hay bịt lối; vẫn sửa chữa cần thiết bình thường.",

            "xk_guide_center": "Trung tâm nhà",
            "xk_guide_front": "Phía hướng",
            "xk_guide_back": "Phía tọa",
            "xk_guide_priority": "Ưu tiên kiểm tra · Chạm để xem",
            "xk_guide_map": "② Chọn phương vị để xem cách bố trí",
            "xk_guide_terms": "Sơn tinh chỉ sự yên tĩnh, nghỉ ngơi và ổn định; hướng tinh chỉ hoạt động, đi lại và thông khí. Khi cùng cung, cần chia công năng. Sao 2/5 được ưu tiên theo nguyên tắc giữ tĩnh. Số sao là ký hiệu, không phải điểm số.",
            "xk_pattern_balanced_title": "Trước hoạt động, sau nghỉ",
            "xk_pattern_balanced_body": "Bàn này đặt trọng tâm hoạt động ở phía hướng, nghỉ ngơi ở phía tọa. Xem phương vị bên dưới; nơi có nhãn “Giữ yên tĩnh” luôn ưu tiên giữ tĩnh.",
            "xk_pattern_front_title": "Chia động tĩnh phía trước",
            "xk_pattern_front_body": "Hoạt động và nghỉ ngơi cùng tập trung ở phía hướng. Chia lối đi và nơi sinh hoạt khỏi chỗ ngồi yên tĩnh, không kích hoạt đồng loạt cả khu.",
            "xk_pattern_back_title": "Chia động tĩnh phía sau",
            "xk_pattern_back_body": "Hoạt động và nghỉ ngơi cùng tập trung ở phía tọa. Xác định phòng thực tế rồi tách lối đi khỏi khu yên tĩnh; không cần đặt vật nặng khắp phía sau.",
            "xk_pattern_reversed_title": "Trước nghỉ, sau hoạt động",
            "xk_pattern_reversed_body": "Hoạt động ở phía tọa, nghỉ ngơi ở phía hướng. Kiểm tra công năng, ánh sáng và tiếng ồn trước khi điều chỉnh nhỏ; không cần cải tạo lớn chỉ vì tên cách cục.",
            "xk_pattern_distributed_title": "Bố trí từng phương",
            "xk_pattern_distributed_body": "Bàn này không thuộc bốn cách cục tập trung trước–sau. Kiểm tra khu cần giữ tĩnh trước, rồi bố trí hoạt động và nghỉ ngơi theo sơ đồ.",
            "xk_use_quiet": "Giữ yên tĩnh",
            "xk_use_separate": "Chia động–tĩnh",
            "xk_use_activity": "Thoáng sáng",
            "xk_use_rest": "Yên tĩnh vững chắc",
            "xk_use_everyday": "Chăm sóc thường ngày",
            "xk_reason_quiet": "Cặp sơn–hướng có 2 hoặc 5 nên theo quy tắc truyền thống cần giữ tĩnh, kể cả khi có sao đương vận cùng hiện diện.",
            "xk_reason_separate": "Sơn tinh và hướng tinh đương vận cùng ở đây nên cần đáp ứng cả hoạt động lẫn nghỉ ngơi yên tĩnh.",
            "xk_reason_activity": "Hướng tinh đương vận ở đây, theo truyền thống là trọng tâm hoạt động, đi lại và nạp khí.",
            "xk_reason_rest": "Sơn tinh đương vận ở đây, theo truyền thống là trọng tâm nghỉ ngơi yên tĩnh và chỗ tựa ổn định.",
            "xk_reason_everyday": "Không có quy tắc ưu tiên sao sơn–hướng đương vận hoặc 2/5 tại đây. Duy trì theo công năng thực tế là đủ.",
            "xk_action_quiet": "Dời thiết bị gây tiếng ồn hoặc rung liên tục, dọn đồ bừa bộn. Nếu là lối vào, vẫn giữ sử dụng bình thường và sửa tiếng cửa kêu hay va đập.",
            "xk_action_separate": "Giữ lối đi và ánh sáng gần cửa; bố trí chỗ ngồi yên tĩnh hoặc nghỉ ngơi phía trong. Dùng nội thất chia nhẹ để các hoạt động không cản trở nhau.",
            "xk_action_activity": "Dọn thoáng cửa và lối đi, sửa chiếu sáng, giữ thông gió. Nếu điều kiện phù hợp, cân nhắc dùng làm nơi sinh hoạt hoặc làm việc.",
            "xk_action_rest": "Giảm tiếng ồn và chói sáng ban đêm, tạo chỗ tựa chắc cho giường hoặc ghế. Giữ thông gió bình thường rồi chỉnh vị trí theo công năng phòng.",
            "xk_action_everyday": "Dọn gọn, bảo đảm ánh sáng, thông gió và lối đi. Sử dụng theo nhu cầu thực tế của bếp, phòng ngủ hay nơi làm việc, không cần sửa thêm.",
            "xk_avoid_quiet": "Không thêm máy bơm, loa để “kích hoạt”, cũng không cần bịt cửa hay ngừng dùng phòng. Vẫn thực hiện sửa chữa cần thiết bình thường.",
            "xk_avoid_separate": "Không đặt TV, loa hay máy bơm sát giường hoặc ghế yên tĩnh; không dùng tủ cao chắn gió hay lối thoát.",
            "xk_avoid_activity": "Không để đồ trang trí chắn cửa hay lối đi; không cần đổi cửa chính, mua bể cá hoặc chiếu sáng chói chỉ vì bàn này.",
            "xk_avoid_rest": "Tránh đặt đầu giường hay ghế sát loa, TV hoặc lối qua lại nhiều; không cần chuyển giường chỉ theo số sao hay đè vật nặng lên giường.",
            "xk_avoid_everyday": "Không cần mua vật phẩm hay chuyển đồ lớn theo số sao; ưu tiên xử lý rò nước, thiếu sáng và lối đi tắc.",

